class GFG {
  public static int repUnitValue ( int n ) {
    if ( n % 2 == 0 n % 5 == 0 ) return 0 ;
    int rem = 1 ;
    int power = 1 ;
    int k = 1 ;
    while ( rem % n != 0 ) {
      k ++ ;
      power = power * 10 % n ;
      rem = ( rem + power ) % n ;
    }
    return k ;
  }
  public static void main ( String [ ] args ) {
    int n = 13 ;
    System . out . println ( repUnitValue ( n ) ) ;
  }
}

