#include <iostream>
#include <cmath>
#include <iomanip>
#include <limits>
#include <string>
#include <vector>
#include <algorithm>
#include <list>
#include <map>
using namespace std;

bool flg=false;

int solve(vector<int> pre,vector<int> in){
    if(pre.size() == 0) return 0;
    if(pre.size() == 1){
        if(flg) cout << ' ';
        cout << pre.at(0);
        flg = true;
    }
    else{
        int root=pre.at(0);
        vector<int> left,right,Lin,Rin;
        for(int i=0;i<in.size();i++){
            if(in.at(i) == root){
                for(int j=0;j<i;j++) left.push_back(in.at(j));
                for(int j=i+1;j<in.size();j++) right.push_back(in.at(j));
                Lin=left,Rin=right;
                sort(left.begin(),left.end());
                sort(right.begin(),right.end());
            }
        }
        for(int i=0;i<pre.size();i++){
            vector<int> l,r,Lpre,Rpre;
            l.clear();
            r.clear();
            for(int j=1;j<i+1;j++) l.push_back(pre.at(j));
            for(int j=i+1;j<pre.size();j++) r.push_back(pre.at(j));
            Lpre=l,Rpre=r;
            sort(l.begin(),l.end());
            sort(r.begin(),r.end());
            bool match=true;
            if(l.size() != left.size()) match=false;
            else{
                for(int k=0;k<l.size();k++){
                    if(l.at(k) != left.at(k)) match=false;
                }
            }
            if(r.size() != right.size()) match=false;
            else{
                for(int k=0;k<r.size();k++){
                    if(r.at(k) != right.at(k)) match=false;
                }
            }
            if(match){
                solve(Lpre,Lin);
                solve(Rpre,Rin);
                cout << ' ' << root;
            }
        }
    }
    return 0;
}

int main(){
    int n;
    cin >> n;
    vector<int> pre(n),in(n);
    for(int i=0;i<n;i++) cin >> pre[i];
    for(int i=0;i<n;i++) cin >> in[i];
    solve(pre, in);
    cout << endl;
}

