    if ( R [ 1 ] > 0 && L [ 1 ] > 0 ) cnt1 = ( R [ 1 ] - L [ 1 ] ) / 2 + 1 ;
    int [ ] [ ] dp = new int [ n + 1 ] [ 3 ] ;
    dp [ 1 ] [ 0 ] = cnt0 ;
    dp [ 1 ] [ 1 ] = cnt1 ;
    for ( int i = 2 ;
    i <= n ;
    i ++ ) {
      dp [ i ] [ 0 ] = ( cnt0 * dp [ i - 1 ] [ 0 ] + cnt1 * dp [ i - 1 ] [ 1 ] ) ;
      dp [ i ] [ 1 ] = ( cnt0 * dp [ i - 1 ] [ 1 ] + cnt1 * dp [ i - 1 ] [ 0 ] ) ;
    }
    return dp [ n ] [ 0 ] ;
  }
  public static void main ( String [ ] args ) {
    int n = 2 , l = 1 , r = 3 ;
    System . out . println ( countWays ( n , l , r ) ) ;
  }
