int checkSemiprime ( int num ) {
  int cnt = 0 ;
  for ( int i = 2 ;
  cnt < 2 && i * i <= num ;
  ++ i ) {
    while ( num % i == 0 ) {
      num /= i ;
      ++ cnt ;
    }
  }
  if ( num > 1 ) ++ cnt ;
  return cnt == 2 ;
}
