  if ( checkSemiprime ( n ) == false ) return false ;
  int r = 0 ;
  for ( int t = n ;
  t != 0 ;
  t = t / n ) r = r * 10 + t % 10 ;
  if ( r == n ) return false ;
  return ( checkSemiprime ( r ) ) ;
}
