            for(int i=0; i<n; i++)
            {
                C[A[i]]++;
            }
            long[] CC = new long[max + 1];//場合の数を記録する
            long sum = 0;//全部の合計
            for (int i = 0; i < max+1; i++)
            {
                if (C[i] == 0 || C[i] == 1) CC[i] = 0;
                else if (C[i] >= 2)
                {
                    long x = C[i];
                    CC[i] = x * (x - 1) / 2;
                }
                sum += CC[i];//全部の場合の数の合計を出しておく
            }
            long res = 0;
            for(int i=0; i<n; i++)//着目する数字をsumから引き、ボール一個減らした分だけsumに足す
