public static string Transpose(string s, int rows, int columns) {
    int n = s.Length;
    if (rows * columns != n) throw new System.ArgumentException();
    System.Text.StringBuilder sb = new System.Text.StringBuilder();
    for (int i = 0; i < n - 1; i++) sb.Append(s[(i * columns) % (n - 1)]);
    sb.Append(s[n - 1]);
    return sb.ToString();
}

