    {
        struct SAYING
        {
            public int men;
            public int isLie;

        }


        static void Main(string[] args)
        {
            int N = int.Parse(Console.ReadLine());

            List<SAYING>[] say = new List<SAYING>[N];
            for (int i = 0; i < N; i++)
            {
                say[i] = new List<SAYING>();
            }

            for (int i = 0; i < N; i++)
            {
                int num = int.Parse(Console.ReadLine());

                for (int j = 0; j < num; j++)
                {
                    string[] s0 = Console.ReadLine().Split(' ');

                    SAYING t;
                    t.men = int.Parse(s0[0]) - 1;
                    t.isLie = int.Parse(s0[1]);

                    say[i].Add(t);
                }
            }

            int ans = 0;
            int maxnum = (int)Math.Pow(2, N);
            for (int i = 0; i < maxnum; i++)
            {
                int localans = 0;
                bool valid = true;

                for (int j = 0; j < N; j++)
                {
                    int bit = 1 << j;

                    // 1＝正直者を検査
                    if(0 != (i & bit))
                    {
                        bool testOK = true;
                        foreach(SAYING st in say[j])
                        {
                            int bit2 = 1 << st.men;

                            if(
                                ((st.isLie == 0) && (0 != (i & bit2))) ||
                                ((st.isLie != 0) && (0 == (i & bit2)))
                                )
                            {
                                testOK = false;
                                break;
                            }
                        }

                        if(!testOK)
                        {
                            valid = false;
                            break;
                        }
                    }
                }

                if(valid)
                {
                    for (int j = 0; j < N; j++)
                    {
                        if(0 != (i & (1<<j)))
                        {
                            localans++;
                        }
                    }

                    ans = Math.Max(ans, localans);
                }
            }

            Console.WriteLine(ans);
        }
    }
}

