		long[,,] dp = new long[n+1,t+1,2];//dp[見た数、使った時間、短縮済か]:=価値の最大値
    long[,] vertexes = new long[n,2];
    long answer = 0;
    for(int i = 0; i < n; i++)
    {
      long[] numsa = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
      vertexes[i,0] = numsa[0];
      vertexes[i,1] = numsa[1];
    }

    for(int i = 1; i <= n; i++)
    {
      for(int j = 0; j <= t; j++)
      {
        dp[i,j,0] = dp[i-1,j,0];
        if(j-vertexes[i-1,0] >= 0)
          dp[i,j,0] = Math.Max(dp[i,j,0], dp[i-1, j-vertexes[i-1,0], 0]+vertexes[i-1,1]);

        dp[i,j,1] = dp[i-1,j,1];
        if(j-vertexes[i-1,0] >= 0)
          dp[i,j,1] = Math.Max(dp[i,j,1], dp[i-1, j-vertexes[i-1,0],1]+vertexes[i-1,1]);
        if(j-1 >= 0)
          dp[i,j,1] = Math.Max(dp[i,j,1], dp[i-1,j-1, 0]+vertexes[i-1,1]);
      }
    }

    for(int i = 0; i <= t; i++)
    {
      for(int j = 0; j <= 1; j++)
