{
    using (var fs = new System.IO.FileStream(fileName, System.IO.FileMode.Open)) 
    {
        byte[] data = new byte[4096];
        int used = 0;
        while(true)
        {
            if (data.Length - used < 4096)
            {
                byte[] newData = new byte[data.Length * 2];
                Array.Copy(data, 0, newData, 0, used);
                data = newData;
            }
            int got = fs.Read(data, used, data.Length - used);
            if (got <= 0) break;

            used += got;
        }
        var encoding = charsetName != null ? System.Text.Encoding.GetEncoding(charsetName) : System.Text.Encoding.UTF8;
        return encoding.GetString(data, 0, used);
    }
}

