def print_path(mat, i, j):
    if len(mat)==0 or len(mat[0])==0:
        print("Empty matrix")
        return
    print("(", i,",", j,")")
    right_value = mat[i][j] if i < 0 or i >= len(mat)-1 or mat[i][j] >= mat[i+1][j] else mat[i+1][j]
    below_value = mat[i][j] if j < 0 or j >= len(mat[0])-1 or mat[i][j] >= mat[i][j+1] else mat[i][j+1]
    above_value = mat[i][j] if i <= 0 or i >= len(mat)-1 or mat[i][j] >= mat[i-1][j] else mat[i-1][j]
    left_value = mat[i][j] if j <= 0 or j >= len(mat[0])-1 or mat[i][j] >= mat[i][j-1] else mat[i][j-1]

    if right_value > left_value:
        if right_value > below_value:
            if right_value > above_value:
                print_path(mat, i + 1, j)
            else:
                print_path(mat, i, j + 1)
        else:
            if below_value > above_value:
                print_path(mat, i - 1, j)
            else:
                print_path(mat, i, j + 1)
    else:
        if left_value > below_value:
            if left_value > above_value:
                print_path(mat, i - 1, j)
            else:
                print_path(mat, i, j + 1)
        else:
            if below_value > above_value:
                print_path(mat, i - 1, j)
            else:
