class Program
{
	//static long[,] dp;
	//static	Dictionary<string, long> dp;
	//static int[] weight, value;
    //static List<string> str = new List<string>();
	//static int INT_MAX = 1000000007;
	static void Main(string[] args)
	{
			// 入力フェーズ
			int N = Int32.Parse(Console.ReadLine());
			string[] input = Console.ReadLine().Split(' '); // p1, p2... pn
			//int H = Int32.Parse(input[0]);
			//int W = Int32.Parse(input[1]);
			Decimal[] pob = new Decimal[N];
			for(int i=0; i< N; i++)
			{
				pob[i] = Decimal.Parse(input[i]);
			}

			// i枚目まで投げて、j枚表になる確率
			Decimal[,] dp = new Decimal[N+1,N+1];
			dp[1,1] = pob[0]; // 初期値
			dp[1,0] = 1 - pob[0]; // 裏になる
			for(int i=1; i<N; i++)
			{
				for(int j=0; j<=N; j++)
				{
					if(i+1 < j)
					{
						// i+1枚投げてi+1枚以上表になることはないので
						break;
					}
					// i+1枚投げて、j枚表になる確率は。。。
					// i枚投げてj-1枚表になっている→i+1枚目が表になる確率
					// + i枚投げて j枚表になっている→i+1枚目が裏になる確率

					if(j==0)
					{
						// j-1<0なので
						dp[i+1, j] = dp[i, j] * (1 - pob[i]);
					}
					else
					{
						dp[i+1, j] = dp[i, j] * (1 - pob[i])
													+ dp[i, j-1] * pob[i];
					}
				}
			}

			// 表になるコインが半分より大きい確率は
			int half = N/2 + 1; // half枚以降を足し合わせる

			Decimal ret = 0;
			for(int j=half; j<=N; j++)
			{
				ret += dp[N, j];
			}

			Console.WriteLine(ret + "");
    }
}

