			int v = sc.nextInt()-1;
			int a = sc.nextInt();
			int b = sc.nextInt();
			Edge e = new Edge();
			e.from=u;
			e.to=v;
			e.yen=a;
			e.snuke=b;
			Edge f = new Edge();
			f.from=v;
			f.to=u;
			f.yen=a;
			f.snuke=b;

			graph.get(u).edges.add(e);
			graph.get(v).edges.add(f);
		}


