			int count = 0;
			long cost = 0;
			int now = A[i];
			Set<Integer> set = new HashSet<Integer> ();
			for (; count < N && count < K; count++) {
				if (set.contains(now)) {
					break;
				}
				set.add(now);
				cost += C[now];
				now = A[now];
				if (cost > max) {
					max = cost;
				}
